export const fromFSM = <TIn, TOut>(
		lItems:  TIn[],
		lStates: TStateDesc<TIn, TOut>[]
		): TOut => {

	try {
		let state = 0
		let i1 = 0;for (const item of lItems) {const i = i1++;
			const {stateFunc, retFunc} = lStates[state]
			state = handleItem(item, stateFunc, retFunc, i)
		}

		const {retFunc} = lStates[state]
		obviously(inRange(state, lStates.length))
		if (defined(retFunc)) {
			return retFunc()
		}
		else {
			return croak(`End state ${state} not a final state`)
		}
	}
	catch (x) {
		if (x instanceof Error) {
			throw x
		}
		else {
			return x as TOut
		}
	}
}

// ---------------------------------------------------------------------------

const handleItem = <TIn, TOut>(
		item:      TIn,
		stateFunc: TStateFunc<TIn, TOut>,
		retFunc: (  TReturnFunc<TOut> | undefined),
		i: number
		): TStateNum => {

	const result = stateFunc(item, i)

	// --- If we throw, it's a TOut to return to caller of fromFSM
	if (isArray(result)) {
		throw result[1]
	}
	else if (result === -1) {
		assert(defined(retFunc), "Return -1 without a TReturnFunc")
		throw retFunc()
	}
	else {
		return result
	}
}

